// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    Attacker attacker;

    function setUp() public { c = new C(); attacker = new Attacker(); }

    // fuzzed params: depositor address (non-zero) and deposit amount
    function testFuzz_property(address depositor, uint256 amount) public {
        // keep depositor a usable EOA-like actor
        vm.assume(depositor != address(0));
        // bound amount to a reasonable range so vm.deal works and to avoid overflow in the test env
        uint256 amt = bound(amount, 1, 1 ether);

        // fund depositor and attacker
        vm.deal(depositor, amt);
        vm.deal(address(attacker), 1 ether);

        // depositor deposits amt into c
        vm.prank(depositor);
        c.deposit{value: amt}();

        // Now attacker will be used as the recipient in withdrawAll by making attacker be msg.sender
        // The attacker is malicious: its receive() will reenter withdrawAll to attempt to exploit the buggy ordering
        // Make sure attacker has a credit as well to perform a normal withdraw later if needed
        vm.prank(address(attacker));
        c.deposit{value: 1 wei}();

        // Now trigger withdrawAll from attacker (so attacker will receive the payout and reenter)
        // Use try/catch to call withdrawAll and capture whether it reverted; the property we assert is about state
        bool ok;
        vm.prank(address(attacker));
        try c.withdrawAll() {
            ok = true;
        } catch {
            ok = false;
        }

        // The universal property for the correct contract: after withdrawAll returns (whether success or not), the caller's credit must be zero.
        // We read the credit via the public getter that solidity creates for mapping: credit(address) -> uint
        // (Note: the contract's mapping is named `credit` in the provided source.)
        // The single required assertion: caller's credit is zero. This holds for the reference; the mutant is exploitable by reentrancy
        assertTrue(c.credit(address(attacker)) == 0);
    }
}

// Attacker contract that re-enters withdrawAll during receive
contract Attacker {
    bool public first = true;

    receive() external payable {
        // re-enter only once to try to exploit ordering differences
        if (first) {
            first = false;
            // attempt to reenter the victim contract; note: victim address must be known by the test via c
            // The test will have set up c and made this contract have credit; we call back into C.withdrawAll
            // We need to obtain the caller's context: the test calls c.withdrawAll() with msg.sender = address(this), so reenter below
            // To perform the reentrancy we try to call withdrawAll on the caller (msg.sender is the victim contract during the transfer)
            // But we cannot access that here; instead the test orchestrates by making this contract the initial caller of c.withdrawAll.
            // So reentrancy occurs by calling back into the last-known victim address stored in tx.origin via assembly is not allowed.
            // To keep this helper minimal and usable, the test entry calls c.withdrawAll with msg.sender == address(this), so inside receive we can call back
            // The victim contract address will be pushed into calldata by the test via using the same C instance; so we need a reference.
            // We leave reentrancy attempt to be triggered by the test's known C instance by calling C(msg.sender).withdrawAll();
            // msg.sender in this context is the contract that sent Ether to this Attacker, i.e., the C instance.
            C(payable(msg.sender)).withdrawAll();
        }
    }
}

