pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzzed: deposit amount and attacker starting balance
    function testFuzz_property(uint256 depositAmt, uint256 attackerStartBal) public {
        // keep values in reasonable ranges but wide
        depositAmt = bound(depositAmt, 1, 1 ether);
        attackerStartBal = bound(attackerStartBal, depositAmt, 10 ether);

        // deploy attacker which will reenter on receive
        ReentrantAttacker attacker = new ReentrantAttacker(address(c));

        // fund attacker externally so it can deposit
        vm.deal(address(attacker), attackerStartBal);

        // attacker deposits depositAmt into c
        attacker.depositTo{value: depositAmt}();

        // Now attacker calls withdrawAll which for the reference contract should
        // leave its recorded credit at zero (no leftover), whereas the mutant
        // that moves zeroing before the external call allows reentrancy to
        // alter final state in a way the fuzzer can detect. We observe c only.
        bool ok;
        try attacker.triggerWithdraw() {
            ok = true;
        } catch {
            ok = false;
        }

        // The invariant: after withdrawAll completes on the reference C, the
        // attacker's recorded credit is zero. We read via the auto getter credit(address).
        // This must be true for the correct contract for all inputs; the mutant
        // that allows reentrancy to reuse credit will cause this to be false for some inputs.
        assertTrue(c.credit(address(attacker)) == 0);
    }
}

// Minimal reentrant attacker that reenters once during receive
contract ReentrantAttacker {
    C public target;
    bool public entered;
    constructor(address _t) {
        target = C(_t);
    }

    // deposit helper
    function depositTo() external payable {
        (bool s, ) = address(target).call{value: msg.value}(abi.encodeWithSignature("deposit()"));
        require(s);
    }

    // trigger withdraw through this contract so receive() will be called
    function triggerWithdraw() external {
        (bool s, ) = address(target).call(abi.encodeWithSignature("withdrawAll()"));
        require(s);
    }

    receive() external payable {
        // on first entry, try to reenter withdrawAll to exploit mutant
        if (!entered) {
            entered = true;
            // reenter
            (bool s, ) = address(target).call(abi.encodeWithSignature("withdrawAll()"));
            // ignore success
            s;
        }
    }
}

