    function setUp() public { c = new C(); }

    // fuzz params: depositAmount (how much is deposited) and attackerStartBalance (attacker/beneficiary ether)
    function testFuzz_property(uint96 depositAmount, uint96 attackerStartBalance) public {
        // keep amounts in a reasonable wide domain but non-zero deposit
        depositAmount = uint96(bound(uint256(depositAmount), 1, 1e18));
        attackerStartBalance = uint96(bound(uint256(attackerStartBalance), 0, 1e20));

        // deploy attacker helper that will reenter during receive
        Attacker attacker = new Attacker(address(c));

        // fund attacker externally so it can receive and make calls
        vm.deal(address(attacker), attackerStartBalance);

        // make the attacker the depositor: it will deposit depositAmount into c
        vm.deal(address(this), depositAmount); // ensure this test has funds to forward

        // perform deposit from attacker
        // we need to have attacker call deposit on c sending Ether; use attacker helper to forward
        attacker.depositTo{value: depositAmount}();

        // record contract balance before withdraw
        uint256 before = address(c).balance;

        // now perform withdrawAll as the attacker; attacker.receive will reenter to try to exploit mutant
        bool ok;
        try attacker.callWithdrawAll() {
            ok = true;
        } catch {
            ok = false;
        }

        // After withdraw completes, the correct contract should have decreased balance by exactly depositAmount
        // and thus address(c).balance == before - depositAmount. The mutant allowing reentrancy may make balance smaller.
        // We assert the universal property (one assertion): that the contract's balance after is >= before - depositAmount.
        // For the correct contract this holds for all inputs; the mutant can violate it (making balance < before - depositAmount).
        assertTrue(address(c).balance >= before - depositAmount);
    }
}

// Minimal adversarial helper: will act as depositor and as a reentrant beneficiary.
contract Attacker {
    address payable target;
    bool reentered;
    constructor(address _target) payable {
        target = payable(_target);
    }

    // depositTo forwards Ether to c.deposit()
    function depositTo() external payable {
        // call deposit on C
        (bool s,) = target.call{value: msg.value}(abi.encodeWithSignature("deposit()"));
        require(s);
    }

    // call withdrawAll on C as this contract (beneficiary) so receive() can reenter
    function callWithdrawAll() external {
        (bool s,) = target.call(abi.encodeWithSignature("withdrawAll()"));
        require(s);
    }

    // receive will attempt one reentrant call back into withdrawAll to exploit mutant that cleared credit early
    receive() external payable {
        if (!reentered) {
            reentered = true;
            // try to reenter withdrawAll; silent ignore failure
            (bool s,) = target.call(abi.encodeWithSignature("withdrawAll()"));
            // do not revert here; we want outer call to continue
            s;
        }
    }
}

