        // fund depositor and make deposit
        vm.deal(depositor, amount);
        vm.prank(depositor);
        c.deposit{value: amount}();

        // call withdrawAll as depositor
        vm.prank(depositor);
        // withdrawAll is external/public and may revert; capture outcome
        bool ok;
        try c.withdrawAll() {
            ok = true;
        } catch {
            ok = false;
        }

        // If withdraw succeeded, the reference contract guarantees credit[depositor] == 0
        // We read via the public getter auto-generated for the mapping (credit is public in src)
        // (If withdraw reverted, we cannot assert the zeroing property because state unchanged.)
        if (ok) {
